        if(careComposer!=null)root.addView(careComposer);playerBar=u.column();root.addView(playerBar);player();bottom();setContentView(root);root.requestApplyInsets();scroll.post(()->scroll.scrollTo(0,position));root.getViewTreeObserver().addOnGlobalLayoutListener(()->{android.graphics.Rect r=new android.graphics.Rect();root.getWindowVisibleDisplayFrame(r);boolean keyboard=root.getRootView().getHeight()-r.bottom>u.dp(180);if(bottomBar!=null)bottomBar.setVisibility(keyboard?View.GONE:View.VISIBLE);});if(restoreForm!=null){JSONObject draft=restoreForm;restoreForm=null;app.main.post(()->{edit(draft.optJSONObject("previous"),draft.optString("kind"));if(formFrom!=null){formFrom.setText(draft.optString("from"));formUntil.setText(draft.optString("until"));formAmount.setText(draft.optString("amount"));formNote.setText(draft.optString("note"));formDetail.setSelection(draft.optInt("detail"));formCaregiver.setSelection(draft.optInt("caregiver"));}});}
