        sectionAction("照护提醒","全部",()->nav("reminders"));if(reminders.isEmpty())u.item(body,"没有待办提醒","","添加",this::addReminder);else{JSONObject r=reminders.get(0);u.item(body,r.optString("title"),datetime(r.optLong("due"))+(r.optLong("due")<System.currentTimeMillis()?" · 已到时间":""),"完成",()->work(()->Reminders.done(this,r.optString("id")),"提醒已完成"));}
