        sectionAction("最近照护","全部记录",()->nav("records"));if(timeline.isEmpty())u.add(body,u.label("还没有记录，点上方快捷登记即可开始。"),4);else for(int i=Math.max(0,timeline.size()-3);i<timeline.size();i++){JSONObject e=timeline.get(i);u.item(body,CareTimeline.actor(e.optString("caregiver_name"))+" · "+CareTimeline.action(e.optString("kind"),e.optDouble("amount"),e.optString("detail"),e.optLong("duration"),e.optInt("active")==1),time(e.optLong("start")),null,()->details(e));}schedulePoll();
