    private void schedulePoll(){if(shouldPoll()&&!aiPollInFlight){app.main.removeCallbacks(pollJobs);app.main.postDelayed(pollJobs,1500);}if(pendingJob()&&aiPollAttempts>=40)u.add(body,u.button("继续查询回复",false,()->{aiPollAttempts=0;app.network.execute(()->AiEngine.process(app));}),8);}
