    private void playTrack(JSONObject t){voice.cancel();PlaybackService.play(this,t.optString("title"),t.optString("url"),"white_noise".equals(t.optString("category")));}
    private void playRain(){app.database.execute(()->{try{File f=DiskMedia.ambience(this);app.main.post(()->PlaybackService.play(this,"轻雨 · 离线环境音",f.getAbsolutePath(),true));}catch(Exception e){app.main.post(()->toast("雨声暂时不可用，请重试"));}});}
    private void routeCare(String content){if(prompt==null)return;String text=content.trim();if(text.isEmpty()){toast("先说一句或输入文字");return;}voice.cancel();prompt.clearFocus();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(prompt.getWindowToken(),0);IntentRouter intent=IntentRouter.classify(text);
        drafts.put("care","");prompt.setText("");
        switch(intent.action){
            case "clarify":routeStatus="请一次说一个动作；记录会先确认，不会自动保存。";refresh();break;
            case "records":nav("records");break;case "handoff":nav("handoff");break;case "family":nav("my");break;case "updates":nav("updates");break;case "reminder":addReminder();break;
            case "audio":category=intent.category;if(text.contains("雨声")){app.database.execute(()->{try{File f=DiskMedia.ambience(this);app.main.post(()->PlaybackService.play(this,"轻雨 · 离线环境音",f.getAbsolutePath(),true));}catch(Exception e){app.main.post(()->toast("雨声暂时不可用，请重试"));}});}else nav("audio");break;
            case "stop":PlaybackService.control(this,"stop");break;case "pause":PlaybackService.control(this,"pause");break;case "resume":PlaybackService.control(this,"resume");break;
            case "sleep_start":confirmSleep(true);break;case "sleep_end":confirmSleep(false);break;
            case "record":String detail="feeding".equals(intent.kind)?text.contains("母乳")?"母乳":text.contains("奶粉")?"奶粉":"其他":"diaper".equals(intent.kind)?text.contains("便")?text.contains("尿")?"尿便都有":"大便":text.contains("尿")||text.contains("湿")?"尿湿":"":"";JSONObject candidate=Store.obj("id","","kind",intent.kind,"start",System.currentTimeMillis(),"end",0,"amount",decimalAmount(text),"detail",detail,"note",text,"require_end",IntentRouter.historical(text)&&"sleep".equals(intent.kind));edit(candidate,intent.kind);if(IntentRouter.historical(text)){formFrom.setText("");toast("请确认这次补记的实际发生时间");}break;
            default:mode="story".equals(intent.action)?"story":"qa";sendAi(mode);
        }
    }
    private static double decimalAmount(String text){return CareRules.voiceQuantity(text);}
    private void confirmSleep(boolean start){if(start==(active!=null)){toast(start?"已经在记录睡眠，可先结束当前睡眠":"当前没有进行中的睡眠");return;}new AlertDialog.Builder(this).setTitle(start?"开始记录睡眠？":"宝宝已醒，结束睡眠？").setMessage("照护对象："+child+"；时间："+datetime(System.currentTimeMillis())).setNegativeButton("取消",null).setPositiveButton("确认",(d,w)->sleepToggle()).show();}
