    private void timeline(int max){
        if(timeline.isEmpty()){LinearLayout empty=u.card(body,u.surface);u.add(empty,u.text("这一天还没有记录",18,u.ink,true),0);u.add(empty,u.label("记一次喂奶或换尿布，就会留下谁、何时、做了什么。"),8);return;}
        boolean undated=false;int count=Math.min(max,timeline.size());
        for(int i=0;i<count;i++){
            JSONObject e=timeline.get(i);boolean unknown=e.optLong("start")==0;
            if(unknown&&!undated){u.section(body,"发生时间未登记","以下记录不计入这一天的合计。");undated=true;}
            String clock=CareTimeline.clock(e.optLong("start"),zone,date),actor=CareTimeline.actor(e.optString("caregiver_name"));
            String action=CareTimeline.action(e.optString("kind"),e.optDouble("amount"),e.optString("detail"),e.optLong("duration"),e.optInt("active")==1);
            LinearLayout row=u.row();row.setGravity(Gravity.TOP);TextView timeLabel=u.text(clock,large()?14:15,u.muted,true);timeLabel.setGravity(Gravity.END);timeLabel.setPadding(0,u.dp(18),u.dp(6),0);row.addView(timeLabel,new LinearLayout.LayoutParams(u.dp(large()?90:68),-2));
            View rail=new TimelineRail(this,u,i==0||unknown&&timeline.get(Math.max(0,i-1)).optLong("start")!=0,i==count-1||i+1<count&&timeline.get(i+1).optLong("start")==0&&!unknown);row.addView(rail,new LinearLayout.LayoutParams(u.dp(18),-1));
            LinearLayout card=u.column();card.setPadding(u.dp(12),u.dp(12),u.dp(12),u.dp(12));card.setBackground(u.shape(u.surface,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.bottomMargin=u.dp(8);cp.leftMargin=u.dp(6);row.addView(card,cp);
            u.add(card,u.text(actor,18,u.ink,true),0);u.add(card,u.text(action,16,u.ink,false),6);
            if("feeding".equals(e.optString("kind"))&&!e.optString("detail").isEmpty())u.add(card,u.label(e.optString("detail")),6);
            if(e.optInt("pending")>0)u.add(card,u.label("待同步"),6);if(!e.optString("note").isEmpty())u.add(card,u.label(e.optString("note")),6);
            card.setClickable(true);card.setFocusable(true);card.setContentDescription(actor+"，"+clock.replace('\n',' ')+"，"+action+"，点按查看详情");card.setOnClickListener(v->details(e));u.add(body,row,0);
        }
    }
